css:
/* ---------------------------------------------------------------
   Nivel dibujado con --w-frac (0..1).

   El truco es calc(): la altura del líquido es el porcentaje de llenado.

       height: calc(var(--w-frac) * 100%);

   Con --w-frac = 0.5 el tanque se llena a la mitad. Sin JavaScript.
   --------------------------------------------------------------- */

.tanque {
  display: flex;
  flex-direction: column;
  align-items: center;
  gap: 6px;
  width: 100%;
  height: 100%;
  padding: 6px;
}

.cuerpo {
  position: relative;
  flex: 1;
  width: 100%;
  overflow: hidden;

  border: 3px solid var(--w-border-color);
  border-radius: 10px 10px 16px 16px;
  background: rgba(148, 163, 184, 0.12);
}

.liquido {
  position: absolute;
  left: 0;
  right: 0;
  bottom: 0;

  height: calc(var(--w-frac) * 100%);
  background: linear-gradient(180deg, var(--w-color), color-mix(in srgb, var(--w-color) 70%, black));
  transition: height 0.3s ease;
}

/* Brillo en la superficie del líquido: lo que hace que parezca líquido y no
   una barra de progreso girada. */
.liquido::before {
  content: '';
  position: absolute;
  top: 0;
  left: 0;
  right: 0;
  height: 4px;
  background: rgba(255, 255, 255, 0.45);
}

.marcas {
  position: absolute;
  inset: 0;
  display: flex;
  flex-direction: column;
  justify-content: space-evenly;
  pointer-events: none;
}

.marcas span {
  height: 1px;
  margin-left: 60%;
  background: rgba(148, 163, 184, 0.5);
}

.valor {
  font-size: var(--w-font-size);
  font-weight: var(--w-bold);
  color: var(--w-color);
  white-space: nowrap;
}

/* Aviso de nivel alto: la clase la pone widget.js */
.tanque.alto .valor { color: #ef4444; }

js:
// El CSS ya dibuja el nivel solo con --w-frac. El JavaScript se usa aquí
// únicamente para lo que el CSS no puede hacer: decidir por umbral.
//
// Un widget puede perfectamente NO tener .js y reaccionar solo con las
// variables CSS... salvo por el detalle del permiso de scripts. Ver el LEEME.

window.onWidgetUpdate = function (w) {
  var t = document.querySelector('.tanque');
  if (!t) return;

  // Por encima del 90 % el número se pone rojo.
  t.classList.toggle('alto', w.frac > 0.9);
};
